import{_ as r,c as t,o,a5 as n}from"./chunks/framework.BTBXp1_p.js";const f=JSON.parse('{"title":"ADR-001: No Refresh Tokens in browserAuth","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-no-refresh-tokens.md","filePath":"adr/001-no-refresh-tokens.md","lastUpdated":1769357072000}'),a={name:"adr/001-no-refresh-tokens.md"};function i(s,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /oauth-callback/adr/001-no-refresh-tokens.md for this page in Markdown format</div><h1 id="adr-001-no-refresh-tokens-in-browserauth" tabindex="-1">ADR-001: No Refresh Tokens in browserAuth <a class="header-anchor" href="#adr-001-no-refresh-tokens-in-browserauth" aria-label="Permalink to “ADR-001: No Refresh Tokens in browserAuth”">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2025-01-25 <strong>Tags:</strong> oauth, mcp, security</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>Should <code>browserAuth</code> handle OAuth refresh tokens and automatic token renewal?</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li><code>browserAuth</code> intentionally does not request or handle refresh tokens.</li><li>When tokens expire, <code>tokens()</code> returns <code>undefined</code>, signaling the MCP SDK to re-authenticate.</li><li>The SDK&#39;s built-in retry logic handles re-auth transparently.</li></ul><p>Rationale:</p><ul><li><strong>MCP SDK lifecycle</strong>: The SDK expects auth providers to return <code>undefined</code> for expired tokens, triggering its standard re-auth flow.</li><li><strong>CLI/desktop UX</strong>: Interactive re-consent is acceptable and often preferred over silent background refresh.</li><li><strong>Simplicity</strong>: Avoiding refresh eliminates token rotation complexity, race conditions, and concurrent refresh handling.</li><li><strong>Security</strong>: No long-lived refresh tokens stored; each session requires explicit user consent.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>Implement refresh flow</strong> — Adds complexity (token rotation, concurrency), conflicts with SDK&#39;s re-auth expectations, stores long-lived credentials.</li><li><strong>Optional refresh via config</strong> — Increases API surface, creates two divergent code paths to maintain.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: Simpler implementation, predictable behavior, aligns with MCP SDK design.</li><li>Negative/Risks: More frequent browser prompts for long-running sessions (acceptable for CLI tools).</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code: <code>src/auth/browser-auth.ts</code></li><li>Related: MCP SDK auth interface in <code>@modelcontextprotocol/sdk/client/auth</code></li></ul>',15)])])}const p=r(a,[["render",i]]);export{f as __pageData,p as default};
